__mods__ = {}
def reg_mod(nm, src): __mods__[nm] = src
def get_mod(nm:str, v:int, debugger:bool=False):
    if not (src := __mods__.get(f'{nm}_{v}', __mods__.get(nm))):
        src = f'console.log("[{nm}] ES module version `{v}` not found");'
        debugger = False
    return Response(('debugger;\n' if debugger else '')+src, media_type='text/javascript')

