def ensure_server(srv=None, port=8000, app=None, mods=None, app_kw=None, **jupyuvi_kw):
    "Return a live server, served app, route decorator, and preview helper; existing servers win"
    srv,_ = _ensure_server(srv=srv, port=port, app=app, app_kw=app_kw, reuse=True, **jupyuvi_kw)
    setup_loader(srv.app, mods)
    return (*srv_bundle(srv),)

async def ensure_server_a(srv=None, port=8000, app=None, mods=None, app_kw=None, **jupyuvi_kw):
    "Return a live async server, served app, route decorator, and preview helper; existing servers win"
    srv,_ = await _ensure_server_a(srv=srv, port=port, app=app, app_kw=app_kw, reuse=True, **jupyuvi_kw)
    setup_loader(srv.app, mods)
    return (*srv_bundle(srv),)

