def log(msg, *args, **kwargs): print(f"[{datetime.now():%H:%M:%S}] {msg}", flush=True)

# %% ../nbs/02_server.ipynb #f95cf689
class LoggerHandler(logging.Handler):
    def __init__(self, log): self.log = log; super().__init__()
    def emit(self, record):
        try: self.log(f"{(record.levelname+':'):<10}{self.format(record)}")
        except Exception: self.handleError(record)

# %% ../nbs/02_server.ipynb #deed061f
def setup_uvi_logging(_log=None, level=logging.INFO):
    "Route uvicorn logs to `_log`, returning a cleanup function"
    _log = log if _log is None else _log
    _lh = LoggerHandler(_log)
    names = ('uvicorn', 'uvicorn.error', 'uvicorn.access')
    prev = {}
    for name in names:
        lg = logging.getLogger(name)
        prev[name] = lg.handlers[:],lg.propagate,lg.level,lg.disabled
        lg.handlers,lg.propagate,lg.disabled = [_lh],False,False
        lg.setLevel(level)
    def cleanup():
        for name,(handlers,propagate,level,disabled) in prev.items():
            lg = logging.getLogger(name)
            lg.handlers,lg.propagate,lg.disabled = handlers,propagate,disabled
            lg.setLevel(level)
    return cleanup

# %% ../nbs/02_server.ipynb #085b35d6
@asynccontextmanager
async def serve_app(
    app=None, # FastHTML app to serve; if omitted, create one with `app_kw`
    port=8000, # Port to serve on; `None` chooses a free non-public port
    srv=None, # Existing server to use; must already be live
    reuse=True, # Reuse an existing live server on `port`
    after_start=None, # Optional callback run after server is available
    before_stop=None, # Optional callback run before owned-server teardown
    restore_routes=True, # Restore `app.routes` after the block for owned servers
    timeout=5, # Seconds to wait for owned server port to become free
    mods=None,  # ESM modules to register
    app_kw=None, # Keyword args for default app creation
    **jupyuvi_kw):
    "Yield a live JupyUviAsync server for a test block; reuse only when allowed, cleanup only when owned, restore owned routes"
    srv,own = await _ensure_server_a(srv=srv, port=port, app=app, app_kw=app_kw, reuse=reuse, **jupyuvi_kw)
    routes,err = list(srv.app.routes) if own and restore_routes and hasattr(srv.app, 'routes') else None,None
    setup_loader(srv.app, mods)
    try:
        if after_start: await maybe_await(after_start(srv))
        yield srv
    except Exception as e: err = e
    try:
        if before_stop: await maybe_await(before_stop(srv))
    except Exception as e:
        if err is None: err = e
    try:
        if routes is not None: srv.app.routes[:] = routes
    except Exception as e:
        if err is None: err = e
    if own:
        srv.server.should_exit = True
        deadline = (loop := asyncio.get_running_loop()).time() + timeout
        while not is_port_free(srv.port, srv.host):
            if loop.time() > deadline:
                e = TimeoutError(f"Port {srv.host}:{srv.port} still in use after {timeout}s")
                if err is None: err = e
                break
            await asyncio.sleep(0.1)
    if err: raise err

