async def load_mod(nm, src, v=None):
    "Inject ES module `nm` with source `src` into the browser"
    async with serve_app() as _: res = await js_eval_a(f'''return await import("/esm/{nm}{('?v='+v) if v else ''}")''')
    return res

async def setup_mod(nm, src, add_v=False):
    "Register and inject ES module `nm`+optional version with source `src` into the browser"
    nmv = f"{nm}{'_'+str(v) if (v := str(kntr(nm)) if add_v else None) else ''}"
    reg_mod(nmv, src)
    return nmv, await load_mod(nm, src, v)

