@delegates(link_msg)
async def add_js_msg(nm:str, id:str=None, dname:str='', **kwargs) -> str|None:
    fl,_,src = (await read_msg(id=id, dname=dname)).content.partition('\n')
    if fl.lower() not in ('%%javascript', '%%js'): return None
    return await link_msg(f"{nm} = r'''{src}'''", msg_type='code', **kwargs)
